import React from 'react';
import './Hero.css';

export const Hero = () => {
  return (
    <section className="hero-section">

      {/* ── Layer 0: Sky background ── */}
      <img
        src={process.env.PUBLIC_URL + '/bg%20hero.webp'}
        alt=""
        className="hero-bg"
        aria-hidden="true"
        fetchpriority="high"
      />

      {/* ── Layer 1: Vignettes (below all content) ── */}
      <div className="hero-vignette-top"   aria-hidden="true" />
      <div className="hero-vignette-bottom" aria-hidden="true" />

      {/* ── Layer 2: Hills foreground ── */}
      <div className="hero-hills-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/image.webp'}
          alt=""
          className="hero-hills"
          aria-hidden="true"
        />
      </div>

      {/* ── Layer 10: Dashboard card ── */}
      <div className="hero-dashboard-wrapper">
        <img
          src={process.env.PUBLIC_URL + '/hero%20bg%20new.webp'}
          alt="Dishastra app dashboard preview"
          className="hero-dashboard"
        />
      </div>

      {/* ── Layer 20: Text & CTA (always on top) ── */}
      <div className="hero-content">
        <h1 className="hero-title">
          The intelligent travel companion<br />
          for <span className="highlight">every journey you take.</span>
        </h1>
        <p className="hero-subtitle">
          Your journey, our priority. Powered by AI, tailored for you.
        </p>
        <button className="hero-cta">Join the Beta</button>
      </div>

    </section>
  );
};
